/**
 * Universal Code Copy Button Component for pacs008
 * Automatically adds a single "Copy" button to every static <pre><code> block,
 * ensuring interactive tool cards retain their custom header buttons without duplicates.
 */

(function () {
  function initCopyButtons() {
    // 1. Unnest any <pre><code...><pre...> structures generated by syntax highlighters
    document.querySelectorAll("pre pre").forEach(function (innerPre) {
      const parentCode = innerPre.parentElement;
      if (parentCode && parentCode.tagName === "CODE") {
        const outerPre = parentCode.parentElement;
        if (outerPre && outerPre.tagName === "PRE") {
          while (innerPre.firstChild) {
            parentCode.appendChild(innerPre.firstChild);
          }
          innerPre.remove();
        }
      }
    });

    const codeBlocks = document.querySelectorAll("pre");

    codeBlocks.forEach(function (pre) {
      // 2. Ignore nested pre tags
      if (pre.querySelector("pre")) return;
      if (pre.parentElement && pre.parentElement.closest("pre")) return;

      // 3. Skip interactive tool output boxes that have custom header buttons
      if (
        pre.id === "xml-output" ||
        pre.id === "mt103-output" ||
        pre.closest(".interactive-card")
      ) {
        return;
      }

      // 4. Skip if already processed or already contains a code copy button
      if (pre.dataset.hasCopyBtn === "true" || pre.querySelector(".code-copy-btn")) {
        return;
      }

      // Mark as processed
      pre.dataset.hasCopyBtn = "true";
      pre.style.position = "relative";

      const btn = document.createElement("button");
      btn.className = "code-copy-btn";
      btn.type = "button";
      btn.innerText = "Copy";
      btn.setAttribute("aria-label", "Copy code snippet");
      btn.style.cssText = `
        position: absolute;
        top: 0.5rem;
        right: 0.5rem;
        padding: 0.25rem 0.6rem;
        font-size: 0.75rem;
        font-weight: 600;
        color: var(--ink-soft);
        background: var(--bg-alt);
        border: 1px solid var(--rule);
        border-radius: 4px;
        cursor: pointer;
        transition: all 0.2s ease;
        opacity: 0.85;
        z-index: 2;
      `;

      btn.addEventListener("mouseenter", function () { btn.style.opacity = "1"; });
      btn.addEventListener("mouseleave", function () { btn.style.opacity = "0.85"; });

      btn.addEventListener("click", function () {
        const code = pre.querySelector("code") || pre;
        const text = code.innerText || code.textContent;

        navigator.clipboard.writeText(text).then(function () {
          btn.innerText = "Copied!";
          btn.style.color = "#0f766e";
          btn.style.borderColor = "#0f766e";

          setTimeout(function () {
            btn.innerText = "Copy";
            btn.style.color = "var(--ink-soft)";
            btn.style.borderColor = "var(--rule)";
          }, 2000);
        });
      });

      pre.appendChild(btn);
    });
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", initCopyButtons);
  } else {
    initCopyButtons();
  }
})();
